#include <stdio.h>

int factorial(int n) {
    if(n < 0) {
        printf("错误：负数没有阶乘\n");
        return -1;
    }
    // 0! 定义为 1。正整数的阶乘通过依次乘上 1 到 n 得到。
    if(n == 0) return 1;
    int result = 1;
    for(int i = 1; i <= n; i++) {
        result *= i;
    }
    return result;
}

int main() {
    int n;
    scanf("%d", &n);
    int result = factorial(n);
    if(result >= 0) printf("%d\n", result);
    return 0;
}
